import{_ as e,c as n,o as r,a3 as t}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Personalización","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/customize.md","filePath":"es/guide/customize.md","lastUpdated":1786595765000}'),i={name:"es/guide/customize.md"};function o(s,a,l,c,d,u){return r(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="personalizacion" tabindex="-1">Personalización <a class="header-anchor" href="#personalizacion" aria-label="Permalink to &quot;Personalización&quot;">​</a></h1><p>Haga que ClipboardxAI funcione a su manera. Esta guía cubre los ajustes que puede ajustar.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>Abra <strong>ClipboardxAI → Ajustes</strong> (o pulse <code>Cmd+,</code>).</p><ul><li><strong>Idioma</strong>: Inglés, 简体中文, 繁體中文, 日本語.</li><li><strong>Inicio al iniciar sesión</strong>: inicia la aplicación automáticamente al iniciar sesión.</li><li><strong>Apariencia</strong>: Claro, Oscuro o Sistema (sigue a macOS).</li></ul><h2 id="configuracion-de-ia" tabindex="-1">Configuración de IA <a class="header-anchor" href="#configuracion-de-ia" aria-label="Permalink to &quot;Configuración de IA&quot;">​</a></h2><p>Configure la IA en la nube en <strong>Ajustes → IA</strong>:</p><table tabindex="0"><thead><tr><th>Ajuste</th><th>Opciones</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Proveedor</strong></td><td>DeepSeek, MiniMax, GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, Gemini</td><td>El servicio compatible con OpenAI a llamar</td></tr><tr><td><strong>API Key</strong></td><td>su clave</td><td>Almacenada en el <strong>Keychain</strong>, nunca se escribe en disco en texto plano</td></tr><tr><td><strong>Modelo</strong></td><td>según proveedor</td><td>El modelo usado para las acciones de IA</td></tr><tr><td><strong>IA en la nube activada</strong></td><td>Activado / Desactivado</td><td>Interruptor maestro para enviar fragmentos a la nube</td></tr></tbody></table><p>La IA en la nube está <strong>desactivada por defecto</strong>. Cuando se activa, su fragmento se envía solo al proveedor que configuró.</p><h2 id="acciones" tabindex="-1">Acciones <a class="header-anchor" href="#acciones" aria-label="Permalink to &quot;Acciones&quot;">​</a></h2><p>Personalice cómo se comportan las herramientas:</p><ul><li><strong>Ejecutar automáticamente al generar</strong>: cuando está activado, la herramienta seleccionada se ejecuta automáticamente en el momento en que copia.</li><li><strong>Aplicaciones excluidas</strong>: las aplicaciones de esta lista se omiten por la supervisión del portapapeles y la ejecución automática (p. ej., gestores de contraseñas).</li><li><strong>Orden de herramientas</strong>: en la ventana de la Herramienta de IA, arrastre las herramientas instaladas para reordenarlas; su orden se recuerda.</li></ul><h2 id="privacidad" tabindex="-1">Privacidad <a class="header-anchor" href="#privacidad" aria-label="Permalink to &quot;Privacidad&quot;">​</a></h2><p>Abra <strong>Ajustes → Privacidad</strong>:</p><ul><li><strong>Opción de IA en la nube</strong>: el interruptor maestro para enviar datos a un proveedor.</li><li><strong>Aplicaciones excluidas</strong>: detenga la captura de aplicaciones concretas.</li><li><strong>Controles del historial</strong>: gestione cuánto tiempo se conservan los fragmentos en su dispositivo.</li></ul><p>Todo el historial permanece local. No subimos fragmentos ni ejecutamos analítica.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>Gestione las acciones instaladas:</p><ul><li><strong>Explorar</strong>: abra <strong>Marketplace</strong> desde la ventana de la Herramienta de IA o desde el sitio.</li><li><strong>Instalar</strong>: haga clic en <strong>Instalar</strong> en una acción para añadirla mediante un enlace profundo.</li><li><strong>Eliminar</strong>: desinstale una acción de su lista de <strong>Instaladas</strong>.</li></ul><h2 id="barra-de-menu" tabindex="-1">Barra de menú <a class="header-anchor" href="#barra-de-menu" aria-label="Permalink to &quot;Barra de menú&quot;">​</a></h2><ul><li><strong>Mostrar en la barra de menú</strong>: active/desactive el icono de la bandeja.</li><li><strong>Salir al cerrar</strong>: elija si la aplicación sigue en ejecución en segundo plano.</li></ul><h2 id="sugerencias" tabindex="-1">Sugerencias <a class="header-anchor" href="#sugerencias" aria-label="Permalink to &quot;Sugerencias&quot;">​</a></h2><ul><li>Mantenga la IA en la nube desactivada hasta que la necesite — las herramientas locales cubren la mayoría de la limpieza diaria.</li><li>Añada gestores de contraseñas y aplicaciones de entrada segura a <strong>Aplicaciones excluidas</strong> para que los secretos nunca se capturen.</li><li>Combine la ejecución automática con una herramienta local para una limpieza de texto sin manos en cada copia.</li></ul>',23)])])}const m=e(i,[["render",o]]);export{g as __pageData,m as default};
